  W("celebrate", "/ˈselɪbreɪt/", V, "святкувати", "We celebrate my birthday.", "Ми святкуємо мій день народження."),
  W("anniversary", "/ˌænɪˈvɜːsəri/", N, "річниця", "Today is their wedding anniversary.", "Сьогодні річниця їхнього весілля."),
